"""실행기 화면에 쓰는 거래소 로고 — 웹(frontend/public/exchanges)과 같은 그림을 크기별 PNG 로 담는다.

단일 exe 로 배포하므로 파일을 따로 두지 않는다. 화면 배율에 맞는 크기를 골라 쓴다(늘리지 않고 고른다 —
Tk 의 정수 확대·축소는 계단이 생긴다). 다시 만들 때: ImageMagick 으로 Lanczos 축소 후 base64.
"""
from __future__ import annotations

import tkinter as tk

SIZES = (18, 23, 24, 27, 30, 36, 48)
_LOGOS = {
    "binance": {
        18: "",
        23: "",
        24: "",
        27: "",
        30: "",
        36: "",
        48: "",
    },
    "upbit": {
        18: "",
        23: "",
        24: "",
        27: "",
        30: "",
        36: "",
        48: "",
    },
    "bithumb": {
        18: "",
        23: "",
        24: "",
        27: "",
        30: "",
        36: "",
        48: "",
    },
}


def logo(master, exchange: str, size: float):
    """size(화면 픽셀)에 가장 가까운 크기의 로고. 모르는 거래소는 None."""
    table = _LOGOS.get(str(exchange).lower())
    if not table:
        return None
    best = min(SIZES, key=lambda n: (abs(n - size), -n))
    return tk.PhotoImage(master=master, data=table[best], format="png")
